const LANGUAGE_TAGS = { zh: 'zh-CN', en: 'en', ja: 'ja' };
const LANGUAGE_STORAGE_KEY = 'xiv-player-language';
let language = 'zh';
try {
  const saved = localStorage.getItem(LANGUAGE_STORAGE_KEY);
  if (saved && TRANSLATIONS[saved]) language = saved;
} catch { /* Storage can be unavailable. */ }

export const LANGUAGES = Object.freeze([
  { id: 'zh', label: '简体中文' },
  { id: 'en', label: 'English' },
  { id: 'ja', label: '日本語' },
]);

export function getLanguage() { return language; }
export function getLanguageTag() { return LANGUAGE_TAGS[language] || LANGUAGE_TAGS.zh; }
export function setLanguage(value) {
  if (!TRANSLATIONS[value]) return language;
  language = value;
  try { localStorage.setItem(LANGUAGE_STORAGE_KEY, language); } catch { /* Storage can be unavailable. */ }
  return language;
}
export function t(key, values = {}) {
  const template = TRANSLATIONS[language]?.[key] ?? TRANSLATIONS.zh[key] ?? key;
  return template.replace(/\{\{(\w+)\}\}/g, (_, name) => String(values[name] ?? ''));
}
export function applyStaticTranslations(root = document) {
  for (const element of root.querySelectorAll('[data-i18n]')) element.textContent = t(element.dataset.i18n);
  for (const element of root.querySelectorAll('[data-i18n-title]')) element.title = t(element.dataset.i18nTitle);
  for (const element of root.querySelectorAll('[data-i18n-aria-label]')) element.setAttribute('aria-label', t(element.dataset.i18nAriaLabel));
  for (const element of root.querySelectorAll('[data-i18n-placeholder]')) element.placeholder = t(element.dataset.i18nPlaceholder);
  document.documentElement.lang = getLanguageTag();
  document.title = t('document.title');
  document.querySelector('meta[name="description"]')?.setAttribute('content', t('document.description'));
}
